-- @dsh-bridge/server-kit: the Bridge tables, MySQL 8 / TiDB dialect of migrations/001_bridge.sql (same tables, columns,
-- unique rules and index names). Differences:
--   * jsonb -> JSON (no JSON defaults: the store always writes the value); timestamptz -> DATETIME(6) holding UTC
--     (the store writes UTC_TIMESTAMP(6); createMysqlPool sets the session time_zone to '+00:00' for the defaults).
--   * uuid -> CHAR(36), generated by the store (crypto.randomUUID). Indexed text -> VARCHAR, the rest TEXT.
--   * utf8mb4_bin everywhere: text compares exactly as in PostgreSQL (ids, tokens, hashes).
--   * partial unique indexes (WHERE ...) -> a virtual column that is 1 while the row is "live" and NULL otherwise, last in
--     the unique index (NULLs never collide), under the same index name.
--   * bridge_event.id is NOT auto-increment: ids come from the one-row counter bridge_event_seq, taken under a row lock in
--     the writing transaction, so ids commit in increasing order (TiDB's AUTO_INCREMENT is not monotonic across servers).
--   * other increasing ids (audit log, throttle hits): AUTO_INCREMENT with TiDB's AUTO_ID_CACHE=1 (globally increasing
--     allocation on TiDB; only a comment for MySQL).
-- One statement per ";" at the end of a line (the runner splits on it).

create table if not exists bridge_setting (
  `key` varchar(64) not null primary key,
  value text not null
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;

create table if not exists bridge_throttle_hit (
  id bigint not null auto_increment primary key,
  bucket varchar(191) not null,
  `key` varchar(255) not null,
  at datetime(6) not null default current_timestamp(6),
  key bridge_throttle_hit_lookup (bucket, `key`, at),
  key bridge_throttle_hit_bucket (bucket, at)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin /*T![auto_id_cache] AUTO_ID_CACHE=1 */;

create table if not exists bridge_audit_log (
  id bigint not null auto_increment primary key,
  at datetime(6) not null default current_timestamp(6),
  actor varchar(191) not null,
  action varchar(191) not null,
  target text,
  detail json not null,
  key bridge_audit_log_action (action, at)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin /*T![auto_id_cache] AUTO_ID_CACHE=1 */;

create table if not exists bridge_identity (
  id char(36) not null primary key,
  user_id varchar(191) not null,
  platform varchar(64) not null,
  team_id varchar(191) not null default '',
  external_id varchar(191) not null,
  bot_id varchar(191),
  method varchar(32) not null default 'link_code',
  verified_at datetime(6) not null default current_timestamp(6),
  created_at datetime(6) not null default current_timestamp(6),
  unlinked_at datetime(6),
  live_key tinyint as (if(unlinked_at is null, 1, null)) virtual,
  unique key bridge_identity_active (platform, team_id, external_id, live_key),
  key bridge_identity_user (user_id)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;

create table if not exists bridge_link_code (
  id char(36) not null primary key,
  user_id varchar(191) not null,
  code_hash varchar(128) not null,
  created_at datetime(6) not null default current_timestamp(6),
  expires_at datetime(6) not null,
  used_at datetime(6),
  revoked_at datetime(6),
  live_key tinyint as (if(used_at is null and revoked_at is null, 1, null)) virtual,
  unique key bridge_link_code_live (code_hash, live_key),
  key bridge_link_code_user (user_id)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;

create table if not exists bridge_personal_bot (
  id char(36) not null primary key,
  user_id varchar(191) not null,
  platform varchar(64) not null,
  bot_id varchar(191) not null,
  created_at datetime(6) not null default current_timestamp(6),
  revoked_at datetime(6),
  unique key bridge_personal_bot_platform_bot_id_key (platform, bot_id),
  key bridge_personal_bot_user (user_id)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;

create table if not exists bridge_assistant_ticket (
  id char(36) not null primary key,
  token_hash varchar(128) not null,
  user_id varchar(191) not null,
  session_id varchar(191) not null,
  created_at datetime(6) not null default current_timestamp(6),
  expires_at datetime(6) not null,
  revoked_at datetime(6),
  unique key bridge_assistant_ticket_token_hash_key (token_hash),
  key bridge_assistant_ticket_session (session_id)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;

create table if not exists bridge_delegation (
  id char(36) not null primary key,
  token_hash varchar(128) not null,
  user_id varchar(191) not null,
  identity_id char(36),
  session_id varchar(191),
  ticket_id char(36),
  created_at datetime(6) not null default current_timestamp(6),
  expires_at datetime(6) not null,
  revoked_at datetime(6),
  unique key bridge_delegation_token_hash_key (token_hash),
  key bridge_delegation_identity (identity_id),
  key bridge_delegation_user (user_id),
  key bridge_delegation_ticket (ticket_id),
  constraint bridge_delegation_identity_id_fkey foreign key (identity_id) references bridge_identity (id),
  constraint bridge_delegation_ticket_id_fkey foreign key (ticket_id) references bridge_assistant_ticket (id)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;

-- transactional outbox: written in the same transaction as the business change
create table if not exists bridge_event (
  id bigint not null primary key,
  event_type varchar(191) not null,
  aggregate_type varchar(191) not null,
  aggregate_id varchar(191) not null,
  payload json not null,
  created_at datetime(6) not null default current_timestamp(6)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;

-- the event id counter (one row): insertEvent increments it under the row lock of its transaction
create table if not exists bridge_event_seq (
  id tinyint not null primary key,
  last_id bigint not null,
  constraint bridge_event_seq_id_check check (id = 1)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;
insert ignore into bridge_event_seq (id, last_id) values (1, 0);

create table if not exists bridge_notification_pref (
  user_id varchar(191) not null primary key,
  types json not null,
  quiet_hours json,
  updated_at datetime(6) not null default current_timestamp(6)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;

create table if not exists bridge_delivery (
  event_id bigint not null,
  user_id varchar(191) not null,
  status varchar(32) not null default 'pending',
  channel varchar(64),
  message_ref text,
  error_code varchar(191),
  resolved_at datetime(6) not null default current_timestamp(6),
  updated_at datetime(6) not null default current_timestamp(6),
  primary key (event_id, user_id),
  constraint bridge_delivery_status_check check (status in ('pending', 'sent', 'failed', 'skipped', 'undeliverable')),
  constraint bridge_delivery_event_id_fkey foreign key (event_id) references bridge_event (id)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;

create table if not exists bridge_approval_delivery (
  id char(36) not null primary key,
  approval_id varchar(191) not null,
  user_id varchar(191) not null,
  identity_id char(36) not null,
  token_hash varchar(128) not null,
  status varchar(32) not null default 'issued',
  wrong_attempts integer not null default 0,
  message_ref text,
  sent_at datetime(6),
  expires_at datetime(6) not null,
  created_at datetime(6) not null default current_timestamp(6),
  live_key tinyint as (if(status in ('issued', 'locked'), 1, null)) virtual,
  unique key bridge_approval_delivery_token_hash_key (token_hash),
  unique key bridge_approval_delivery_live (approval_id, user_id, live_key),
  key bridge_approval_delivery_user (user_id, status),
  key bridge_approval_delivery_identity (identity_id),
  constraint bridge_approval_delivery_status_check check (status in ('issued', 'used', 'revoked', 'locked')),
  constraint bridge_approval_delivery_identity_id_fkey foreign key (identity_id) references bridge_identity (id)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;

create table if not exists bridge_report (
  id char(36) not null primary key,
  kind varchar(191) not null,
  report_date date not null,
  slot varchar(32) not null,
  sections json not null,
  attention integer not null default 0,
  test boolean not null default false,
  created_by varchar(191),
  generated_at datetime(6) not null default current_timestamp(6),
  scheduled_key tinyint as (if(test, null, 1)) virtual,
  unique key bridge_report_scheduled (kind, report_date, slot, scheduled_key),
  key bridge_report_kind (kind, generated_at)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;

create table if not exists bridge_proposal (
  id char(36) not null primary key,
  kind varchar(191) not null,
  payload json not null,
  status varchar(32) not null default 'pending_review',
  confidence double,
  for_user_id varchar(191),
  created_via varchar(32) not null,
  created_at datetime(6) not null default current_timestamp(6),
  decided_by varchar(191),
  decided_at datetime(6),
  comment text,
  key bridge_proposal_created (created_at),
  constraint bridge_proposal_status_check check (status in ('pending_review', 'accepted', 'rejected')),
  constraint bridge_proposal_created_via_check check (created_via in ('service', 'delegation'))
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin;
